INSERT INTO "AR_Relations" (from_id, to_id, relation_type) VALUES ('laudine', 'yvain', 'marriage') ON CONFLICT (from_id, to_id, relation_type) DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('arthur', 'Geoffrey of Monmouth', 'In the Historia Regum Britanniae (c.1136), Arthur is first cast as a continental war-king: he subdues the Saxons at Mount Badon, crosses the sea to conquer Ireland, Iceland, Norway, and Gaul, and is on the very edge of Rome when Mordred''s betrayal calls him home. Geoffrey''s Arthur is more emperor than mystic — there is no Round Table, no Grail, and Guinevere flees to a nunnery without much fuss.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('arthur', 'Wace', 'Wace''s Roman de Brut (1155) translates Geoffrey into Norman French octosyllabics and adds, almost in passing, the Round Table itself — invented so that none of Arthur''s lords might claim precedence over another. The piece of furniture eats the legend whole.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('arthur', 'Chrétien de Troyes', 'In the late-12th-century romances Arthur recedes: he is the still center, the courteous host at Camelot or Caerleon from which younger, hotter knights ride out on individual aventures. He is rarely the protagonist of his own story anymore.', 3) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('arthur', 'Vulgate Cycle', 'The 13th-century Vulgate makes Arthur the son of an adulterous union, blesses him with the Grail company, and damns him through his own incestuous get on Morgause. He is a tragic Christian king whose Round Table is doomed from the night Mordred is conceived.', 4) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('arthur', 'Malory', 'Malory''s Le Morte d''Arthur (1485) fuses all of this into the canonical English shape: sword in stone, marriage to Guinevere, the long fellowship, the Grail Quest that hollows out the company, the affair of Lancelot, and the final field at Camlann where father and son end each other. He is given to the three queens and borne to Avalon.', 5) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('arthur', 'Spenser', 'In The Faerie Queene (1590) Prince Arthur is a young, pre-coronation knight in search of Gloriana, the Faerie Queene — a chivalric ideal pulled out of legend to flatter Elizabeth I. He is allegory more than man.', 6) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('arthur', 'Tennyson', 'The Idylls of the King (1859–85) cast him as a moral idea wronged by every body he loves: blameless, faintly cold, the still center of a court that corrodes around him.', 7) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('arthur', 'Mark Twain', 'A Connecticut Yankee in King Arthur''s Court (1889) presents him as a credulous, decent provincial — proud, capable of nobility, but a king of an age the Yankee finds barbaric. Twain plainly likes him and plainly disdains his world.', 8) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('arthur', 'T.H. White', 'The Once and Future King (1938–58) gives us the most human Arthur in English: Wart, the small boy taught by Merlyn to think like a fish, a bird, an ant. He grows into a king who genuinely believes Might must serve Right, and who cannot bring himself to hate Lancelot or Guinevere even when he must.', 9) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('arthur', 'Tolkien', 'The Fall of Arthur (composed in the 1930s, published 2013) is an unfinished alliterative poem in Old English meter. Tolkien''s Arthur is in Saxony fighting the heathen when Mordred''s treason recalls him; the verse leaves him at sea, the crossing to Avalon never written.', 10) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('uther', 'Geoffrey of Monmouth', 'Uther is the youngest of three royal brothers (Constans, Aurelius Ambrosius, Uther). He takes the crown after Aurelius is poisoned, fights Saxons, and — at a Christmas feast in London — falls so violently in love with Gorlois''s wife Igraine that Merlin must transform him to gain her bed at Tintagel. Arthur is conceived that night; Gorlois is killed in the same hour.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('uther', 'Wace', 'Wace follows Geoffrey closely but lingers on the sorcery: it is Merlin''s herbs and craft that change Uther, not divine providence. The deception is more clearly a sin.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('uther', 'Vulgate Cycle', 'The Vulgate hardens Uther into a flawed but legitimate Christian king whose lust nonetheless engenders a sacred line. His death is dignified; his ghost is not.', 3) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('uther', 'Malory', 'Malory opens with him: "It befell in the days of Uther Pendragon..." He dies within the first chapters, leaving the infant Arthur to be hidden by Merlin and raised by Ector.', 4) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('uther', 'T.H. White', 'White hardly bothers with Uther — the story has already moved on by the time Wart pulls the sword. He is mentioned mostly as a fact, the way one might mention a grandfather one never met.', 5) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('igraine', 'Geoffrey of Monmouth', 'Geoffrey introduces her as the most beautiful woman in Britain. She is the unwitting instrument of Arthur''s begetting and survives Uther; Geoffrey grants her no further scenes.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('igraine', 'Malory', 'Malory gives her real grief and real bewilderment: when she sees the man who comes to her in Gorlois''s shape, then learns hours later that Gorlois was already dead, she keeps the secret for years out of fear of being thought mad.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('igraine', 'Vulgate Cycle', 'The Vulgate dwells on her three daughters by Gorlois (Morgan, Morgause, Elaine of Garlot) — making her the matriarch of an entire enchantress line that will haunt her son.', 3) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('gorlois', 'Geoffrey of Monmouth', 'A loyal duke who pulls his wife out of Uther''s court to save her from the king. He is killed sallying from a besieged castle in the very hour Uther, disguised, lies with his wife.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('gorlois', 'Malory', 'Malory keeps the tragedy crisp: Gorlois rides out at midnight; Merlin''s glamour falls on Uther in the same moment; both men cannot be Igraine''s husband and yet, for one night, both are.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('ector', 'Malory', 'A good country knight to whom Merlin commits the infant Arthur. He raises Arthur as a younger brother to his own son Kay. When the boy pulls the sword, Ector kneels at once, calls him liege, and weeps. Malory uses him to anchor the whole story in honest, undramatic love.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('ector', 'T.H. White', 'In White he is Sir Ector of the Forest Sauvage — a bluff, gout-prone English squire who calls Arthur "Wart," frets about taxes, and never quite gets over the fact that the boy he raised is the king.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('kay', 'Mabinogion', 'In Culhwch and Olwen, Cai is a giant-tall hero who can hold his breath nine nights, never sleep, and grow as tall as the tallest tree. He is one of the first warriors named at Arthur''s court — older than Camelot.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('kay', 'Chrétien de Troyes', 'Chrétien turns him into a comic boor: sharp-tongued, jealous, the seneschal you don''t invite. The Welsh hero has become a snob in a hall.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('kay', 'Malory', 'Malory keeps Chrétien''s edge but softens it with brotherhood: Kay is rude, brave, often wrong, and Arthur loves him anyway because Kay''s mother nursed Arthur as a baby. He dies fighting in Gaul, far from home.', 3) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('kay', 'T.H. White', 'White''s Kay is a teenager — sulky, awkward, jealous of his foster brother''s strange ease — exactly the older sibling who has been told he is not the chosen one.', 4) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('merlin', 'Geoffrey of Monmouth', 'Geoffrey welds two earlier figures — the Welsh bard Myrddin Wyllt and the fatherless prophet boy Ambrosius — into a single Merlinus Ambrosius. He prophesies the red and white dragons under Vortigern''s tower, moves Stonehenge from Ireland, and engineers Arthur''s conception. Then he vanishes from the Historia.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('merlin', 'Vulgate Cycle', 'The Vulgate''s Estoire de Merlin gives him a demon father (so he is born to know all things past) and a baptismal mother (so he is born to know all things future). His fall is in love: he teaches Nimue every craft until she uses the last spell to seal him in a tower of air.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('merlin', 'Malory', 'Malory keeps the Vulgate end: Nimue ("Nyneve") wearies of his desire, learns his magic, and traps him under a stone in Cornwall. He warns Arthur of his own coming end and goes to it anyway.', 3) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('merlin', 'Spenser', 'In The Faerie Queene Merlin is alive in a cavern beneath the earth, still shaping prophecy for Britomart. He is more force of nature than wizard.', 4) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('merlin', 'Tennyson', '"Merlin and Vivien" is one of the cruelest Idylls: a brilliant old man worn down by a young woman''s flattery until he tells her the binding charm, and is sealed in an oak forever.', 5) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('merlin', 'T.H. White', 'White''s Merlyn lives backwards in time, which is why he is so often confused and so often right. He teaches Wart to be a fish, a hawk, an ant, a badger — and then disappears, having done what he could.', 6) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('morgause', 'Vulgate Cycle', 'The Vulgate is where the incest enters: Morgause comes to Arthur''s court not knowing he is her brother, sleeps with him, and goes home pregnant with Mordred. The doom of the Round Table is conceived in one night.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('morgause', 'Malory', 'Malory keeps the incest and adds an extraordinary later scene: her son Gaheris finds her in bed with Lamorak (decades younger) and strikes off her head, leaving Lamorak alive to be hunted down later by his brothers.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('morgause', 'T.H. White', 'White makes her a witch-queen of Lothian, scheming, neglectful, occasionally tender — the engine of the Orkney faction''s rage. The boys love her too much and badly.', 3) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('lot', 'Geoffrey of Monmouth', 'A loyal lord of Lothian under Arthur, given Orkney as part of Arthur''s northern reorganization.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('lot', 'Malory', 'Malory makes him one of the eleven rebel kings who refuse the boy Arthur. He is killed in battle by King Pellinore — a death his sons (the Orkney brothers) will not forgive, no matter how many years pass.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('gawain', 'Mabinogion', 'As Gwalchmei ("hawk of May") he is one of the very first Arthurian heroes named — a sun-figure whose strength waxes till noon. The Welsh root of all later Gawains.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('gawain', 'Chrétien de Troyes', 'Chrétien''s Gauvain is the model courtier: handsome, courteous, second only to the protagonist of whatever romance he''s in. He is rarely the protagonist himself, but he is always there.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('gawain', 'Sir Gawain and the Green Knight', 'The Pearl Poet (c.1400) gives him the most beautiful single test in English literature: a year and a day to ride to a green chapel and offer his neck to a green axeman. He carries a shield with a pentangle on a purple field — a "endeles knot" of five fives — and he fails by a sash. He survives, and learns, and is ashamed.', 3) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('gawain', 'Malory', 'Malory keeps the courtly polish but adds the family curse: Gawain is the one who, after Lancelot accidentally kills Gareth in the rescue of Guinevere, hounds Lancelot across the channel until his own wound (taken from Lancelot before, and re-opened on landing) kills him. He dies asking Arthur''s forgiveness for his hatred.', 4) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('gawain', 'T.H. White', 'White paints him with a Scots accent and a temper — capable of nobility, fiercely loyal to his brothers, the one who can never quite let a grudge go.', 5) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('gareth', 'Malory', 'The youngest Orkney brother arrives at Camelot in disguise and asks only food and a year in the kitchens. Kay nicknames him "Beaumains" — beautiful hands — for mockery. He earns his spurs by escorting the proud lady Lynette to rescue her sister Lyonesse from the Red Knight of the Red Lands. He becomes the kindest man at the table. Lancelot, fighting unarmed in the rescue of Guinevere, kills him by mistake. It is the wound the fellowship never recovers from.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('gareth', 'T.H. White', 'White makes Gareth the moral center of the Orkney boys — the brother who refuses to hate Lancelot even as Agravain plots, and who dies precisely because of his refusal.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('gaheris', 'Malory', 'The brother who finds his mother Morgause in bed with Lamorak and beheads her on the spot, sparing the knight only so the family can hunt him down later. He is killed beside Gareth in the same disaster — Lancelot, unarmed and trying to save Guinevere, cuts him down without seeing him.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('agravain', 'Vulgate Cycle', 'A jealous, sharp-tongued knight, more politician than warrior. He is the one who first puts into the air the open accusation that Lancelot is sleeping with the queen.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('agravain', 'Malory', 'Agravain and Mordred together force the issue: they catch Lancelot in the queen''s chamber and trigger the war. Lancelot kills Agravain on the spot. Every later death — Gareth, Gaheris, Gawain, Arthur — traces back to that night and that ambush.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('mordred', 'Geoffrey of Monmouth', 'In Geoffrey he is Arthur''s nephew, not yet his son — left as regent and seducer of Guinevere while Arthur is in Gaul. He crowns himself king, and the two armies meet on the Camlann.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('mordred', 'Vulgate Cycle', 'The Vulgate makes him the son of Arthur and Morgause — incest as the original sin of the realm. Every line of the cycle bends toward that final field.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('mordred', 'Malory', 'Malory keeps the Vulgate parentage. Mordred is born for the destruction of his father''s reign; Arthur tries to drown him as an infant, fails, and the boy survives to fulfill the prophecy exactly.', 3) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('mordred', 'T.H. White', 'White''s Mordred is a thin pale boy with a club foot, sick with his mother''s teaching — a study in how a child raised on grievance becomes a terrorist of his father''s house.', 4) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('lancelot', 'Chrétien de Troyes', 'Lancelot enters European literature in Le Chevalier de la Charrette (c.1180), Chrétien''s romance of the queen''s rescue. He is so consumed by love of Guinevere that he hesitates two steps before stepping into the shameful cart that will carry him to her — and Chrétien spends a hundred lines on those two steps.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('lancelot', 'Vulgate Cycle', 'The Vulgate makes him the whole structure: raised by the Lady of the Lake, the greatest knight, the queen''s lover, the one barred from the Grail because of her, and the father, by deception with Elaine of Corbenic, of the knight who will succeed where he cannot.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('lancelot', 'Malory', 'Malory''s Lancelot is both the best and the worst — the knight who can break Camelot by being in it. He survives Arthur. He goes to a hermitage with Bors, dies in odor of sanctity, and Ector (his brother) gives one of the great eulogies in English: thou wert the truest lover of a sinful man that ever loved woman.', 3) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('lancelot', 'Tennyson', 'Tennyson''s Lancelot is the broken honorable man — wracked, eloquent, doomed by a single love.', 4) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('lancelot', 'T.H. White', 'White''s Lancelot is the "Ill-Made Knight" — physically ugly, ferociously gifted, certain he is damned, in love with Arthur and with Guinevere in ways that don''t resolve.', 5) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('guinevere', 'Geoffrey of Monmouth', 'Geoffrey''s Guanhumara is Roman-Briton noble; she takes Mordred as consort during Arthur''s absence, then flees to a Caerleon nunnery when he returns. Geoffrey gives her no inner life.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('guinevere', 'Chrétien de Troyes', 'Chrétien is the first to make her an active object of courtly love — Lancelot risks his soul, his honor, and a series of obstacles to reach her bed. She is sharp-tongued and unafraid of giving orders.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('guinevere', 'Malory', 'Malory''s queen is generous and jealous in equal measure, repeatedly endangering Lancelot through fits of suspicion that turn out to be true. At the end she takes the veil at Amesbury and refuses to see Lancelot one last time, "for as much as I am the cause of all this war." She dies abbess.', 3) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('guinevere', 'Tennyson', '"Guinevere" — perhaps the bitterest of the Idylls — has her prostrate before Arthur at Almesbury while he forgives her in such terms as to ruin them both.', 4) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('guinevere', 'T.H. White', 'White is unusually fair to her: he refuses the Victorian habit of blaming the queen for the kingdom''s fall, and gives her real intelligence, real boredom, real love.', 5) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('galahad', 'Vulgate Cycle', 'The Queste del Saint Graal (c.1225) introduces Galahad as the prophesied Good Knight — conceived when Elaine of Corbenic, enchanted to look like Guinevere, lies with Lancelot. He sits in the Siege Perilous, achieves the Grail at Sarras, asks God to let him die, and is taken up. He is the Grail Quest''s only complete success.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('galahad', 'Malory', 'Malory keeps every beat of the Queste but makes Galahad more bearable by sheer plainness. He arrives in red armor, breaks the swords of others by being more worthy, and dies in Sarras with the Grail in his eye.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('galahad', 'Tennyson', '"Sir Galahad" is Tennyson''s most-quoted Idyll — the perfect virginal knight whose "strength is as the strength of ten."', 3) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('percival', 'Chrétien de Troyes', 'Perceval, ou Le Conte du Graal (c.1190) gives the world the Grail — but only at a feast in a wounded king''s hall, where Perceval, raised in the forest and told not to ask too many questions, watches the procession in silence and so fails. Chrétien died with the romance unfinished.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('percival', 'Wolfram von Eschenbach', 'Parzival (c.1210) is the German answer: a vast romance in which Parzival redeems his failure, learns compassion, becomes Grail King. Wagner read it.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('percival', 'Mabinogion', 'In the Welsh Peredur the Grail is a head on a platter; the romance reads older and stranger, closer to the otherworld.', 3) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('percival', 'Vulgate Cycle', 'The Vulgate makes him secondary to Galahad — a worthy Grail companion, but not the chosen knight. He dies a hermit.', 4) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('percival', 'Malory', 'Malory follows the Vulgate but keeps Percival''s rustic, watchful innocence intact. He is one of the three to reach Sarras, and the only one of the three to come back, briefly, to tell Camelot what they saw.', 5) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('bors', 'Vulgate Cycle', 'Bors is the third Grail companion and the only one to return to Camelot alive. He is the steady moral keel — the knight who will refuse to lie even when his cousin Lancelot needs him to. His Quest features an agonizing choice: rescue his brother Lionel from torture, or save a maiden from rape. He chooses the maiden. Lionel survives, and almost kills him for it.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('bors', 'Malory', 'Malory loves Bors. He is the witness — the one who sees, judges, and goes on. He carries Lancelot''s ashes into a hermitage after the king and queen are dead.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('lionel', 'Vulgate Cycle', 'Bors''s brother. Captured by enemy knights in the Quest and tortured nearly to death. When Bors rides past to save a maiden instead of him, Lionel survives in such a rage that he tries to kill his brother in single combat.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('lionel', 'Malory', 'Malory keeps the fratricidal moment and makes it terrifying — a hermit and a knight throw themselves between the brothers and are killed for it. The two are reconciled only by miracle.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('ector-marais', 'Malory', 'Not to be confused with old Sir Ector who raised Arthur. This Ector is Lancelot''s half-brother — also of the Lake. He gives the great eulogy at Lancelot''s death, the longest sustained piece of lyrical prose in Malory: "Thou wert never matched of earthly knight''s hand…"', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('bedivere', 'Mabinogion', 'As Bedwyr he is the oldest companion — paired with Cai (Kay), the two earliest names at Arthur''s side in the Welsh tradition.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('bedivere', 'Geoffrey of Monmouth', 'A high officer in Arthur''s continental campaigns. Killed in Gaul fighting Romans.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('bedivere', 'Malory', 'Malory keeps him alive for the very end. After Camlann, Arthur asks him three times to throw Excalibur back into the lake. Bedivere lies twice — the sword is too beautiful to lose — and only on the third asking does he obey. He is the last man at Arthur''s side as the barge of queens carries the king away.', 3) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('bedivere', 'Tennyson', '"The Passing of Arthur" gives Bedivere two of the most famous lines in nineteenth-century English: he describes Excalibur being caught by an arm clothed in white samite.', 4) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('tristan', 'Other early sources', 'The Tristan story is older than Arthurian romance — Welsh Drystan, Pictish, Cornish. It enters French romance in the 12th century via Béroul, Thomas of Britain, and the verse fragments survive only as scraps.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('tristan', 'Vulgate Cycle', 'The Prose Tristan (c.1230) folds him fully into the Arthurian world, making him a member of the Round Table and a foil to Lancelot — two adulterous knights, two doomed loves.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('tristan', 'Malory', 'Malory''s Book of Sir Tristram is the longest single book in the Morte. He drinks the love potion meant for King Mark and Isolde on the ship from Ireland and never recovers. He dies, in Malory, of treachery — Mark stabs him in the back while he is harping for Isolde.', 3) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('tristan', 'Tennyson', '"The Last Tournament" gives him a sardonic late hour: he is no longer the romantic hero but a man who has outlived his own story.', 4) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('lamorak', 'Malory', 'Reputedly the third-best knight of the Round Table, after Lancelot and Tristan. His father Pellinore killed King Lot of Orkney in battle long before, and the Orkney brothers never forgave it. Lamorak''s affair with Morgause — Lot''s widow — was the spark: Gaheris beheaded her in bed and the brothers ambushed and killed Lamorak weeks later, four against one.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('pellinore', 'Vulgate Cycle', 'Pellinore hunts the Questing Beast — Glatisant — through forest after forest. The beast has the head of a serpent, body of a leopard, hindquarters of a lion, feet of a hart, and a noise in its belly as of thirty couple hounds. The hunt was a quest no one could finish; it passed from Pellinore to Palamedes.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('pellinore', 'Malory', 'Malory keeps the Beast and adds the political crime: Pellinore killed Lot of Orkney in the rebel-kings'' war. He is later killed in turn by Gawain — vengeance taking a generation.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('pellinore', 'T.H. White', 'White''s Pellinore is comic and beloved — a befuddled, exhausted middle-aged king who pursues the Beast because he doesn''t know what else to do, eventually falls in love with the Beast itself, and is rescued only when it cures his loneliness.', 3) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('palamedes', 'Vulgate Cycle', 'A great Saracen knight who comes to Logres unbaptized and falls hopelessly in love with Isolde of Ireland. The Prose Tristan made him Tristan''s great rival in love. He inherits the hunt of the Questing Beast from Pellinore.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('palamedes', 'Malory', 'Malory loves him — gives him real interior life, real grief, and finally has him baptized by Galahad in the Quest of the Grail. He kills the Questing Beast at last.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('safir', 'Malory', 'Palamedes''s brother. A solid Saracen knight, also eventually baptized.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('segwarides', 'Malory', 'The third Saracen brother. Tristan once seduced his wife — a minor scandal in a book that has bigger ones.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('yvain', 'Chrétien de Troyes', 'Yvain, ou Le Chevalier au Lion (c.1180) is the strangest of Chrétien''s romances: Yvain marries the widow of a knight he killed, forgets to come home, goes mad in the forest, and is restored by — among other things — a lion he saves from a serpent. The lion follows him for the rest of the romance.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('yvain', 'Mabinogion', 'The Welsh Owain ap Urien is the historical kernel: a 6th-century king of Rheged. The romance retains a Welsh flavor of fountains and otherworlds.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('yvain', 'Malory', 'Malory keeps him a member of the Round Table but tells little of his own story; he is mostly seen riding with Gawain.', 3) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('geraint', 'Chrétien de Troyes', 'Erec et Enide (c.1170) is the earliest Chrétien romance and the first European novel of married love. Erec falls into uxoriousness, hears his wife weeping over how her love has ruined him, and forces them both on a long humiliating road to test her and himself.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('geraint', 'Mabinogion', 'The Welsh Geraint son of Erbin is a Cornish lord, fully redrafting the romance into a Welsh idiom.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('geraint', 'Tennyson', '"Geraint and Enid" pulls it into Victorian poetry — the same story made gentler and more sentimental.', 3) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('enide', 'Chrétien de Troyes', 'Enide''s great test is forbidden speech: her husband orders her not to speak as they ride, and she must break the order every time she sees danger threaten him. The romance is the cumulation of those small disobediences into a real love.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('caradoc', 'Other early sources', 'The Caradoc romances make him the knight of the magic horn — a chastity test that no lady at Arthur''s court but his own wife can pass. It is one of the funnier moments in early French Arthuriana.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('dindrane', 'Vulgate Cycle', 'Percival''s sister joins the three Grail companions on the ship of Solomon. They come to a castle where the lady of the place is dying of leukemia and only the blood of a virgin princess will cure her. Dindrane gives the blood — a silver bowl full — and dies. They lay her body on the ship and it sails to Sarras alone.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('dindrane', 'Malory', 'Malory tells it more briefly but keeps the central image: the silver bowl, the sister''s consent, the empty boat. She is the only woman to "achieve" the Grail.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('blanchefleur', 'Chrétien de Troyes', 'The lady of Beaurepaire whose castle Perceval relieves in his first great deed. Their love is the first thing that begins to teach him what compassion is for.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('lyonesse', 'Malory', 'The proud lady Gareth wins by beating the Red Knight of the Red Lands. Her sister Lynette mocks Gareth for half the romance before consenting to call him a knight.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('mark', 'Other early sources', 'In Béroul''s Tristan (c.1170) Mark is a complicated man — sometimes the cuckold, sometimes a king genuinely trying to be just, sometimes a tyrant. The earlier the source, the more sympathetic.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('mark', 'Malory', 'Malory turns him into a near-villain: cunning, petty, vindictive. He murders Tristan from behind while Tristan is playing the harp for Isolde. It is one of the few deaths in Malory presented as straightforwardly base.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('isolde-ireland', 'Other early sources', 'In Béroul she is a queen of formidable wit and self-possession; in Thomas of Britain the doomed love is everything.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('isolde-ireland', 'Malory', 'Malory keeps her dignity. She dies on Tristan''s body, the second great death-by-love in the Morte. (Lancelot''s is the first.)', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('isolde-hands', 'Other early sources', 'Tristan, in exile from Cornwall, marries her in Brittany — she has the same name as the woman he can''t have. He never sleeps with her. When Tristan lies dying, she lies about the color of the sails of the rescue ship, and he dies of grief minutes before Isolde of Ireland arrives.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('morholt', 'Other early sources', 'The Irish champion who comes to Cornwall to demand tribute. Young Tristan, in his first deed, kills him in single combat — but Morholt''s sword leaves a poisoned shard in Tristan''s side that only Morholt''s niece Isolde of Ireland can heal.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('morgan', 'Geoffrey of Monmouth', 'Geoffrey introduces her in the Vita Merlini (c.1150) not as a villain but as the chief of the nine sisters of Avalon, a healer. Arthur is brought to her after Camlann to be cured.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('morgan', 'Vulgate Cycle', 'The Vulgate turns her against her brother — a pupil of Merlin gone wrong, a witch who steals Excalibur''s scabbard, sleeps with knights to set traps for her brother, and is forever scheming. Yet she is also at the barge that bears him to Avalon at the end.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('morgan', 'Malory', 'Malory keeps the duality. She tries to kill Arthur via her lover Accolon, fails, and is exiled. Decades later, when he is dying at Camlann, she is the first of three queens on the black barge to receive him.', 3) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('morgan', 'Sir Gawain and the Green Knight', 'In the Pearl Poet she is the secret author of the whole trick: it is Morgan who sent the Green Knight to Camelot, hoping to frighten Guinevere to death.', 4) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('morgan', 'T.H. White', 'White separates her sharply from Morgause and makes her a sad, beautiful, malicious fairy of the wet woods.', 5) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('nimue', 'Vulgate Cycle', 'The young enchantress who learns Merlin''s craft from him, falls neither in love nor out, and uses his last great spell to seal him in a cave or air or oak. Her name shifts: Nimue, Niniane, Viviane.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('nimue', 'Malory', 'Malory makes her become the Lady of the Lake after her predecessor''s death — and a kinder figure than the Vulgate. She protects Arthur at several turns, marries Pelleas, and is one of the three queens on the barge to Avalon.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('nimue', 'Tennyson', '"Merlin and Vivien" is the great Victorian portrait of female cunning corroding male wisdom. Tennyson is not subtle about whose side he is on.', 3) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('lady-lake', 'Vulgate Cycle', 'The Lady of the Lake raises Lancelot from infancy in her underwater kingdom. She gives Arthur Excalibur from the lake. The Vulgate often distinguishes her from Nimue/Viviane, who succeeds to the title.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('lady-lake', 'Malory', 'In Malory the original Lady of the Lake comes to Camelot to demand Balin''s head; Balin beheads her instead, on the spot, in Arthur''s hall. The title passes to Nimue. The lake remains.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('pelles', 'Chrétien de Troyes', 'The Fisher King — wounded so he can only fish, waiting for the right question to be asked by the right knight so the wasted land around his castle can heal. Perceval fails to ask.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('pelles', 'Vulgate Cycle', 'Pelles is the Grail-keeper at Corbenic, father of Elaine, grandfather of Galahad. He plots, with his daughter, to bring Lancelot to her bed so the Grail-knight may be conceived.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('pelles', 'Malory', 'Malory keeps Pelles courtly and grave. He is the source of the Grail line on the mother''s side.', 3) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('pellam', 'Malory', 'It is Balin''s "Dolorous Stroke" that wounds Pellam in the thigh with the Spear of Longinus — and that wound creates the Wasteland that the Grail Quest must heal. The blow is one of the first sins of the early Round Table.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('elaine-corbenic', 'Vulgate Cycle', 'Enchanted by her father''s craft to look like Guinevere, she lies with Lancelot at Corbenic. Galahad is conceived. When she later returns to Camelot openly — wearing her own face — Guinevere discovers everything, and Lancelot goes mad in the forest for two years.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('elaine-corbenic', 'Malory', 'Malory tells the story softly. She is a tragic figure, not a schemer — used by her father, faithful to a lover who can never love her back.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('elaine-astolat', 'Malory', 'A young noblewoman who falls in love with Lancelot at a tournament. He cannot return it. She wills herself to die, leaves a letter in her own dead hand, and is floated down to Camelot in a barge of silks. Arthur reads the letter aloud and Guinevere weeps for the first time over Lancelot.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('elaine-astolat', 'Tennyson', '"The Lady of Shalott" is the same girl in a tower. Tennyson made her image — the boat, the mirror cracking — the most-quoted in Arthurian Victoriana.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('elaine-garlot', 'Vulgate Cycle', 'The third daughter of Igraine and Gorlois — the least storied. Married to King Nentres of Garlot; mother of minor knights. She is the sister who does not become an enchantress.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('vortigern', 'Geoffrey of Monmouth', 'The 5th-century king who, in Geoffrey, invites Hengest and the Saxons in as mercenaries against the Picts and so loses Britain to them. His tower collapses every night until the fatherless prophet boy (the young Merlin) explains the red and white dragons fighting in the pool below.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('accolon', 'Malory', 'Morgan steals Excalibur and gives it to her lover Accolon, then arranges for him and Arthur — disarmed and unsuspecting — to be set against each other. Arthur fights nearly to death before recognizing his own sword, gets it back, and forgives Accolon, who dies of his wounds. Morgan is exiled but not punished.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('meleagant', 'Chrétien de Troyes', 'The kidnapper-prince of Le Chevalier de la Charrette. He carries Guinevere off to a kingdom from which no traveler returns; Lancelot pursues her across the Sword Bridge and rescues her. The whole structure of courtly love in French romance rests on this kidnapping.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('meleagant', 'Malory', 'Malory translates it briskly and ends with Lancelot cleaving Meleagant''s helm to the chin.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('bagdemagus', 'Malory', 'A decent old king, father of the villainous Meleagant. He is repeatedly used by Malory as the example of how a worthy father can have a worthless son.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('balin', 'Malory', 'A knight cursed by every act of his own justice. He beheads the Lady of the Lake in Arthur''s own hall. He carries two swords thereafter — one always doomed. He delivers the Dolorous Stroke that wounds King Pellam and creates the Wasteland. Then he and his beloved brother Balan, riding to a strange isle, fail to recognize each other and kill each other in single combat.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('balan', 'Malory', 'The other half of the tragedy. They die in each other''s arms, recognizing too late, and are buried in a single grave with an inscription naming both.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('green-knight', 'Sir Gawain and the Green Knight', 'A green giant rides into Camelot at Christmas with an axe and offers a blow exchanged for a blow a year later. Gawain takes the bargain. The Green Knight is also (it transpires) the courteous Sir Bertilak of Hautdesert, transformed by Morgan le Fay''s sorcery — and the whole test is hers, not his.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('ironside', 'Malory', 'A knight whose strength waxes till noon and wanes after. Beaumains (Gareth) holds him through the morning, then strikes him down in the afternoon. Ironside surrenders and joins the Round Table — one of Malory''s many redemption-by-defeat moments.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('pelleas', 'Malory', 'Pelleas loves the lady Ettarde, who scorns him; Gawain, sent to plead his case, sleeps with her instead. Nimue takes pity, enchants Ettarde to love Pelleas (who now despises her), and marries Pelleas herself.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('pelleas', 'Tennyson', '"Pelleas and Ettarre" is one of the bleaker Idylls — Pelleas survives only to become a wandering disenchanted knight, witness to the collapse of his own ideals.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('lucan', 'Malory', 'Brother to Bedivere. Survives Camlann mortally wounded; tries to lift the dying Arthur and his own guts spill out from the effort. He dies in the king''s arms — one of the small, awful images that ends the Morte.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('urien', 'Mabinogion', 'A historical 6th-century king of Rheged, father of the historical Owain. The Welsh poets remember him.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('urien', 'Malory', 'Married to Morgan. She tries to kill him in his sleep with his own sword; their son Yvain catches her, and she leaves Camelot for good.', 2) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('taliesin', 'Mabinogion', 'The 6th-century historical poet, almost immediately legendary. In Preiddeu Annwfn ("The Spoils of Annwn") he sails with Arthur to the Otherworld to steal a magic cauldron — and only seven return. The poem is older than any Round Table.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('bran', 'Mabinogion', 'From the Second Branch: a giant Welsh king whose head, after his death in Ireland, is buried at the White Tower of London facing south, to guard Britain from invasion forever. Some scholars trace the Grail (the wounded king, the dish that feeds) back to Bran''s cauldron.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('lot-king', 'Vulgate Cycle', 'King of Gaunes; father of Bors and Lionel. Dies in the wars after Arthur''s coronation, leaving his small sons to be raised by the Lady of the Lake alongside Lancelot.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('cador', 'Geoffrey of Monmouth', 'A loyal duke of Cornwall in Geoffrey, one of Arthur''s chief continental commanders. By the later romances he has faded almost entirely.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('ettarde', 'Malory', 'Scorns Pelleas. Sleeps with Gawain. Cursed by Nimue''s enchantment to love Pelleas hopelessly while Pelleas now despises her. She dies of it.', 1) ON CONFLICT DO NOTHING;
INSERT INTO "AR_Sources" (character_id, source, source_text, sort_order) VALUES ('laudine', 'Chrétien de Troyes', 'Yvain kills her husband and, within days, marries her — a transition Chrétien handles with such bald irony that critics have argued about it for eight centuries.', 1) ON CONFLICT DO NOTHING;
